const prior = $('Normalize Transcript Data').first().json;
const raw = $input.first().json;
let text = '';
try {
  if (raw.message && typeof raw.message.content === 'string') {
    text = raw.message.content;
  } else if (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content) {
    text = raw.choices[0].message.content;
  } else if (typeof raw.text === 'string') {
    text = raw.text;
  } else if (typeof raw.content === 'string') {
    text = raw.content;
  } else if (Array.isArray(raw.content)) {
    const block = raw.content.find(b => b.type === 'text');
    text = block ? block.text : '';
  }
} catch (e) {
  throw new Error('Unexpected LLM response shape: ' + JSON.stringify(raw).slice(0, 500));
}
if (!text) {
  throw new Error('Unexpected LLM response shape: ' + JSON.stringify(raw).slice(0, 500));
}
text = text.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + text.slice(0, 500));
}
parsed.summary = parsed.summary || [];
parsed.decisions = parsed.decisions || [];
parsed.action_items = parsed.action_items || [];
parsed.open_questions = parsed.open_questions || [];
parsed.risks = parsed.risks || [];
return [{
  json: {
    ...prior,
    summary: parsed.summary,
    decisions: parsed.decisions,
    action_items: parsed.action_items,
    open_questions: parsed.open_questions,
    risks: parsed.risks
  }
}];

const record = $('Parse Model Output').first().json;
const roster = $input.all()
  .map((i) => i.json)
  .filter((row) => row && (row.name || row.Name || row.aliases || row.jira_account_id || row.slack_member_id));

return [{
  json: {
    ...record,
    roster,
  }
}];

const rec = $input.first().json;
const roster = rec.roster || [];
const norm = (s) => (s || '').toString().trim().toLowerCase();

function findRosterEntry(name) {
  const n = norm(name);
  if (!n) return null;
  return roster.find((r) => {
    const rname = norm(r.name || r.Name);
    const aliases = (r.aliases || '').toString().split(',').map(norm).filter(Boolean);
    return rname === n || rname.startsWith(n) || aliases.includes(n);
  }) || null;
}

const organizerEntry = findRosterEntry(rec.organizer_name);
const unmatchedOwners = [];
const action_items = (rec.action_items || []).map((item) => {
  const match = findRosterEntry(item.owner);
  if (match) {
    return {
      ...item,
      jira_account_id: match.jira_account_id,
      slack_member_id: match.slack_member_id,
      owner_matched: true,
    };
  }
  unmatchedOwners.push(item.owner);
  return {
    ...item,
    jira_account_id: organizerEntry ? organizerEntry.jira_account_id : null,
    slack_member_id: organizerEntry ? organizerEntry.slack_member_id : null,
    owner_matched: false,
    original_owner: item.owner,
  };
});

delete rec.roster;
return [{ json: { ...rec, action_items, unmatchedOwners } }];

const rec = $input.first().json;
const meetingDate = new Date(rec.meeting_date);
const DAYS = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
function addDays(d, n) { const r = new Date(d); r.setDate(r.getDate() + n); return r; }
function toISODate(d) { return d.toISOString().slice(0,10); }
function resolveDate(phrase) {
  if (!phrase) return { iso: null, needs_review: true };
  const p = phrase.toString().trim().toLowerCase();
  if (p === 'today') return { iso: toISODate(meetingDate), needs_review: false };
  if (p === 'tomorrow') return { iso: toISODate(addDays(meetingDate, 1)), needs_review: false };
  let m = p.match(/^in (\d+) days?$/);
  if (m) return { iso: toISODate(addDays(meetingDate, parseInt(m[1], 10))), needs_review: false };
  m = p.match(/^(next|this) (sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
  if (m) {
    const targetDow = DAYS.indexOf(m[2]);
    const curDow = meetingDate.getDay();
    let delta = (targetDow - curDow + 7) % 7;
    if (delta === 0 || m[1] === 'next') delta += 7;
    return { iso: toISODate(addDays(meetingDate, delta)), needs_review: false };
  }
  if (p === 'next week') return { iso: toISODate(addDays(meetingDate, 7)), needs_review: false };
  m = p.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return { iso: p, needs_review: false };
  const parsedNative = new Date(phrase);
  if (!isNaN(parsedNative.getTime())) return { iso: toISODate(parsedNative), needs_review: false };
  return { iso: null, needs_review: true, raw: phrase };
}
const action_items = (rec.action_items || []).map(item => {
  const resolved = resolveDate(item.due_date);
  return { ...item, due_date_raw: item.due_date, due_date: resolved.iso, needs_date_review: resolved.needs_review };
});
return [{ json: { ...rec, action_items } }];

const items = $input.all();
if (items.length === 0) return [];

function flattenItem(j) {
  const nested = (j.action_items && typeof j.action_items === 'object' && !Array.isArray(j.action_items))
    ? j.action_items
    : null;
  if (!nested) return j;
  const flat = { ...j, ...nested };
  delete flat.action_items;
  return flat;
}

const first = flattenItem(items[0].json);
const action_items = items.map((i) => {
  const j = flattenItem(i.json);
  return {
    task: j.task,
    owner: j.owner,
    original_owner: j.original_owner,
    owner_matched: j.owner_matched,
    due_date: j.due_date,
    needs_date_review: j.needs_date_review,
    priority: j.priority,
    slack_member_id: j.slack_member_id,
    jira_key: j.key || null,
  };
});

return [{
  json: {
    meeting_title: first.meeting_title,
    meeting_date: first.meeting_date,
    organizer_name: first.organizer_name,
    project_channel: first.project_channel,
    notion_db_id: first.notion_db_id,
    reminders_enabled: first.reminders_enabled,
    transcript: first.transcript,
    summary: first.summary,
    decisions: first.decisions,
    open_questions: first.open_questions,
    risks: first.risks,
    unmatchedOwners: first.unmatchedOwners,
    action_items,
  }
}];

const rec = $input.first().json;

function textBlock(t) {
  const content = (t || '').toString().slice(0, 1900);
  return { object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content } }] } };
}
function bulletedList(arr) {
  return (arr || []).map((t) => ({
    object: 'block',
    type: 'bulleted_list_item',
    bulleted_list_item: { rich_text: [{ type: 'text', text: { content: t.toString().slice(0, 1900) } }] },
  }));
}
function actionItemLine(a) {
  const owner = a.owner_matched ? a.owner : `${a.owner} (unmatched)`;
  const due = a.due_date ? a.due_date : (a.needs_date_review ? 'NEEDS DATE REVIEW' : 'no due date');
  const jira = a.jira_key ? `[${a.jira_key}]` : '';
  return `${jira} ${a.task} — owner: ${owner}, due: ${due}, priority: ${a.priority}`;
}
function chunk(str, size) {
  const out = [];
  for (let i = 0; i < (str || '').length; i += size) out.push(str.slice(i, i + size));
  return out;
}

const transcriptChunks = chunk(rec.transcript || '', 1900).map(textBlock);
const children = [
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Summary' } }] } },
  ...bulletedList(rec.summary),
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Decisions' } }] } },
  ...bulletedList(rec.decisions),
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Action Items' } }] } },
  ...bulletedList((rec.action_items || []).map(actionItemLine)),
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Open Questions' } }] } },
  ...bulletedList(rec.open_questions),
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Risks' } }] } },
  ...bulletedList(rec.risks),
  { object: 'block', type: 'toggle', toggle: { rich_text: [{ type: 'text', text: { content: 'Full Transcript' } }], children: transcriptChunks.length ? transcriptChunks : [textBlock('(empty)')] } },
];

const dateStart = (rec.meeting_date || '').toString().slice(0, 10);
const notion_payload = {
  parent: { database_id: rec.notion_db_id || '3e20bd9e-55e7-8027-a0be-c79fafca444b' },
  properties: {
    // Matches the Meeting Notes DB title column shown in Notion UI
    Title: { title: [{ text: { content: (rec.meeting_title || 'Untitled meeting').toString().slice(0, 2000) } }] },
  },
  children: children.slice(0, 100),
};

if (/^\d{4}-\d{2}-\d{2}$/.test(dateStart)) {
  notion_payload.properties.Date = { date: { start: dateStart } };
}

return [{ json: { ...rec, notion_payload } }];

const rec = $input.first().json;
function minusHours(iso, h) {
  // Always interpret due dates as 09:00 UTC so reminder_datetime is consistent
  const d = new Date(String(iso).slice(0, 10) + 'T09:00:00.000Z');
  if (Number.isNaN(d.getTime())) return null;
  d.setUTCHours(d.getUTCHours() - h);
  return d.toISOString();
}
const rows = (rec.action_items || [])
  .filter(a => a.due_date)
  .map(a => {
    const reminder_datetime = minusHours(a.due_date, 24);
    if (!reminder_datetime) return null;
    return {
      json: {
        task: a.task,
        owner: a.owner,
        slack_member_id: a.slack_member_id || '',
        channel: rec.project_channel,
        jira_key: a.jira_key || '',
        due_date: a.due_date,
        reminder_datetime,
        sent: false
      }
    };
  })
  .filter(Boolean);
return rows;

const now = Date.now();
const DAY_MS = 24 * 60 * 60 * 1000;

function parseWhen(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    // Google Sheets sometimes returns Excel serial dates
    if (v > 20000 && v < 100000) {
      return new Date(Date.UTC(1899, 11, 30) + v * 86400000);
    }
    const d = new Date(v);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  const s = String(v).trim();
  // Date-only YYYY-MM-DD → treat as 09:00 UTC
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    return new Date(s + 'T09:00:00.000Z');
  }
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
}

function isSent(v) {
  if (v === true || v === 1) return true;
  const s = String(v ?? '').trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === '1' || s === 'y';
}

return $input.all().filter((item) => {
  const j = item.json || {};
  // Skip blank sheet rows
  if (!j.task && !j.reminder_datetime && !j.due_date) return false;
  if (isSent(j.sent)) return false;

  let remindAt = parseWhen(j.reminder_datetime);
  if (!remindAt) {
    const due = parseWhen(j.due_date);
    if (!due) return false;
    remindAt = new Date(due.getTime() - DAY_MS);
  }
  return remindAt.getTime() <= now;
});

const root = $input.first().json;
const body = (root.body && typeof root.body === 'object') ? root.body : root;

function isFathomPayload(b) {
  if (!b || typeof b !== 'object') return false;
  return (
    b.recording_id != null ||
    b.recorded_by != null ||
    Array.isArray(b.calendar_invitees) ||
    (Array.isArray(b.transcript) && b.transcript[0] && b.transcript[0].speaker)
  );
}

function flattenFathomTranscript(transcript) {
  if (!Array.isArray(transcript)) return '';
  return transcript.map((item) => {
    const speaker = (item.speaker && item.speaker.display_name) || 'Unknown';
    const ts = item.timestamp ? `[${item.timestamp}] ` : '';
    const text = (item.text || '').trim();
    return `${speaker} ${ts}: ${text}`;
  }).join('\n');
}

function fileNameToTitle(name) {
  if (!name) return 'Untitled meeting';
  return String(name)
    .replace(/ - n8n extract$/i, '')
    .replace(/\.[^.]+$/, '')
    .replace(/[_-]+/g, ' ')
    .trim() || 'Untitled meeting';
}

function looksLikeBinaryGarbage(text) {
  if (!text) return true;
  const s = String(text);
  return s.startsWith('PK') || s.includes('[Content_Types].xml') || s.includes('word/');
}

function pickDriveText(b) {
  if (typeof b.transcript_text === 'string' && b.transcript_text.trim()) return b.transcript_text.trim();
  if (typeof b.text === 'string' && b.text.trim() && !b.recording_id) return b.text.trim();
  if (Array.isArray(b.text)) return b.text.join('\n\n').trim();
  return '';
}

const DEFAULT_NOTION_DB_ID = '3e20bd9e-55e7-8027-a0be-c79fafca444b';

let transcript;
let attendees;
let meeting_title;
let meeting_date;
let organizer_name;
let project_channel;
let jira_project_key;
let notion_db_id;
let reminders_enabled;
let fathom_share_url = null;
let fathom_recording_id = null;
let source = 'manual';

const driveText = pickDriveText(body);

if (driveText) {
  source = 'google_drive';
  transcript = driveText;

  let driveMeta = {};
  try {
    driveMeta = $('When New Transcript File Added').first().json || {};
  } catch (e) {
    driveMeta = {};
  }

  meeting_title = fileNameToTitle(driveMeta.name || body.name);
  meeting_date = driveMeta.createdTime || driveMeta.modifiedTime || body.createdTime || new Date().toISOString();
  attendees = body.attendees || [];
  organizer_name = body.organizer || body.organizer_name || 'Unknown';
  project_channel = body.slack_channel || body.project_channel || 'C0C0UEMPD5E';
  jira_project_key = body.jira_project_key || 'OPS';
  notion_db_id = body.notion_db_id || DEFAULT_NOTION_DB_ID;
  reminders_enabled = body.reminders_enabled !== false;
} else if (isFathomPayload(body)) {
  source = 'fathom';
  transcript = flattenFathomTranscript(body.transcript);
  attendees = (body.calendar_invitees || [])
    .map((i) => i.name || i.matched_speaker_display_name || i.email)
    .filter(Boolean);
  meeting_title = body.meeting_title || body.title || 'Untitled meeting';
  meeting_date = body.recording_start_time || body.scheduled_start_time || body.created_at || new Date().toISOString();
  organizer_name = (body.recorded_by && body.recorded_by.name) || (attendees[0] || 'Unknown');
  project_channel = body.slack_channel || 'C0C0UEMPD5E';
  jira_project_key = body.jira_project_key || 'OPS';
  notion_db_id = body.notion_db_id || DEFAULT_NOTION_DB_ID;
  reminders_enabled = body.reminders_enabled !== false;
  fathom_share_url = body.share_url || body.url || null;
  fathom_recording_id = body.recording_id || null;

  if (!transcript) {
    throw new Error('Fathom webhook received but transcript is missing. Ensure include_transcript=true on the Fathom webhook.');
  }
} else {
  transcript = body.transcript || '';
  if (Array.isArray(transcript)) {
    transcript = flattenFathomTranscript(transcript) || transcript.join('\n');
  }
  attendees = body.attendees || [];
  meeting_title = body.meeting_title || 'Untitled meeting';
  meeting_date = body.meeting_date || new Date().toISOString();
  organizer_name = body.organizer || body.organizer_name || 'Unknown';
  project_channel = body.slack_channel || body.project_channel || 'C0C0UEMPD5E';
  jira_project_key = body.jira_project_key || 'OPS';
  notion_db_id = body.notion_db_id || DEFAULT_NOTION_DB_ID;
  reminders_enabled = body.reminders_enabled !== false;
}

if (!transcript || !String(transcript).trim()) {
  throw new Error('No transcript text found. Supported Drive files: .docx, .pdf, .txt, or Google Docs.');
}

if (looksLikeBinaryGarbage(transcript)) {
  throw new Error('Transcript still looks like raw DOCX/ZIP bytes. DOCX conversion did not produce plain text.');
}

return [{
  json: {
    source,
    transcript,
    attendees,
    meeting_title,
    meeting_date,
    organizer_name,
    project_channel,
    jira_project_key,
    notion_db_id,
    reminders_enabled,
    fathom_share_url,
    fathom_recording_id,
  }
}];

return $input.all().map((item) => {
  const j = item.json;
  const nested = (j.action_items && typeof j.action_items === 'object' && !Array.isArray(j.action_items))
    ? j.action_items
    : null;
  const flat = nested ? { ...j, ...nested } : { ...j };
  if (nested) delete flat.action_items;

  const task = (flat.task || 'Untitled action item').toString().trim();
  const decisions = (flat.decisions || []).map((d) => `- ${d}`).join('\n');
  const owner = flat.original_owner || flat.owner || 'unknown';

  return {
    json: {
      ...flat,
      jira_summary: task.slice(0, 255),
      jira_description: `Decision context from "${flat.meeting_title || 'Meeting'}" (${flat.meeting_date || ''}):\n\n${decisions || '- (none)'}\n\nOwner as spoken: ${owner}`,
      jira_priority_id: flat.priority === 'high' ? '1' : (flat.priority === 'low' ? '4' : '3'),
    },
  };
});
